const summaries=[{"id":"game-promise","section":"foundations","title":"Game promise and audience fit","purpose":"Make the intended player fantasy and social contract concrete before systems accumulate.","risk":"Vague promises create mismatched expectations and feature sprawl.","signal":"new-player comprehension, return intent, and playtest recall"},{"id":"audience-modes","section":"foundations","title":"Audience modes and player needs","purpose":"Support distinct play styles without forcing every player through the same activity ladder.","risk":"One dominant mode can make the world feel hostile to everyone else.","signal":"mode diversity, completion choice, and sentiment by cohort"},{"id":"design-pillars","section":"foundations","title":"Design pillars and tradeoffs","purpose":"Turn a small set of player-facing values into decisions teams can apply consistently.","risk":"Pillars that never reject features become slogans.","signal":"decision traceability and rejected-scope quality"},{"id":"core-loop","section":"foundations","title":"Moment-to-moment core loop","purpose":"Connect action, feedback, reward, and the next meaningful choice into a satisfying repeatable rhythm.","risk":"Repetition without changing decisions becomes chore work.","signal":"choice frequency, dead time, and voluntary repeat rate"},{"id":"onboarding","section":"foundations","title":"First-time onboarding","purpose":"Teach controls, goals, risk, and social affordances through safe playable steps.","risk":"Long lectures create abandonment before the world has earned trust.","signal":"time to first success and help requests per new player"},{"id":"first-session","section":"foundations","title":"First-session experience","purpose":"Give new players a clear, low-friction path to an early personal win.","risk":"Front-loading menus and currencies hides the fun.","signal":"first-session completion and return after one day"},{"id":"session-geometry","section":"foundations","title":"Session length and activity geometry","purpose":"Make useful activities fit different available play windows while preserving depth.","risk":"Every reward tied to long uninterrupted sessions excludes busy players.","signal":"successful short-session exits and unfinished activity rate"},{"id":"short-play","section":"foundations","title":"Short-session play","purpose":"Let a player make progress, socialize, or explore in a compact session.","risk":"Short play that only advances a timer feels like a teaser.","signal":"meaningful outcomes per 10-minute window"},{"id":"long-term-retention","section":"foundations","title":"Long-term motivation","purpose":"Create durable goals, changing mastery, relationships, and discovery over months.","risk":"Retention built only on fear of loss creates burnout.","signal":"return reasons, goal diversity, and fatigue indicators"},{"id":"player-identity","section":"foundations","title":"Player identity and expression","purpose":"Let characters communicate play style and personality through readable, earned choices.","risk":"Cosmetic hierarchy can make newcomers feel permanently lesser.","signal":"expression variety and recognition without power gaps"},{"id":"customization","section":"foundations","title":"Character customization","purpose":"Offer meaningful self-expression with safe defaults and clear previews.","risk":"Too many irreversible choices increase decision anxiety.","signal":"completion time, regret edits, and use of presets"},{"id":"world-scale","section":"foundations","title":"World scale and density","purpose":"Make the world feel broad while keeping destinations, discoveries, and people reachable.","risk":"A huge empty map turns exploration into transit.","signal":"discovery rate per travel minute and population density"},{"id":"world-travel","section":"foundations","title":"Travel and friction","purpose":"Use travel time to create anticipation, encounters, and social passage rather than dead time.","risk":"Convenience shortcuts can erase world geography; excessive friction strands groups.","signal":"travel-to-play ratio and missed rendezvous"},{"id":"difficulty-ladder","section":"foundations","title":"Difficulty ladder","purpose":"Provide readable steps from learning through mastery and optional high challenge.","risk":"An abrupt spike converts curiosity into failure churn.","signal":"attempt-to-clear curves and voluntary difficulty selection"},{"id":"server-authority","section":"server","title":"Server authority boundaries","purpose":"Let the server validate outcomes that affect fairness, economy, or shared world state.","risk":"Trusting client claims enables desync, duplication, and unfair combat.","signal":"rejected invalid commands and state divergence"},{"id":"client-prediction","section":"server","title":"Client prediction and reconciliation","purpose":"Hide network delay while preserving server-owned truth and understandable correction.","risk":"Large corrections feel like control theft.","signal":"correction distance, correction frequency, and perceived responsiveness"},{"id":"replication","section":"server","title":"State replication contracts","purpose":"Send only the state each client needs, at a cadence the experience can afford.","risk":"Over-replication wastes bandwidth and leaks hidden information.","signal":"bytes per player, stale-state duration, and dropped updates"},{"id":"interest-management","section":"server","title":"Interest management and AOI","purpose":"Deliver nearby, relevant state to each player without arbitrary visibility failures.","risk":"Incorrect boundaries create pop-in, exploits, or invisible threats.","signal":"candidate entities, false negatives, and update budget"},{"id":"sharding","section":"server","title":"Shard and world partitioning","purpose":"Choose world boundaries that preserve community identity while meeting capacity needs.","risk":"Forced fragmentation weakens social persistence.","signal":"friend co-location, transfer failures, and hot-shard saturation"},{"id":"zoning","section":"server","title":"Zone process design","purpose":"Divide simulation responsibilities so local encounters remain responsive and failures contain.","risk":"Zone seams can lose quest or movement state.","signal":"handoff loss, zone load, and cross-zone latency"},{"id":"login-flow","section":"server","title":"Login and session admission","purpose":"Admit authenticated players predictably and protect capacity during bursts.","risk":"A launch queue without clear status feels like a broken game.","signal":"login success by minute, queue abandon rate, and session errors"},{"id":"matchmaking","section":"server","title":"Matchmaking and grouping","purpose":"Form fair, timely groups from player intent, skill, role, latency, and social preference.","risk":"Optimizing queue time alone creates poor matches.","signal":"time to match, early exits, and post-match fairness"},{"id":"party-lifecycle","section":"server","title":"Party lifecycle","purpose":"Keep invites, roles, readiness, instance entry, reconnects, and leadership transitions coherent.","risk":"State split across clients causes silent party failures.","signal":"invite success, leader-loss recovery, and group reassembly"},{"id":"guild-lifecycle","section":"server","title":"Guild lifecycle and governance","purpose":"Support belonging, shared goals, succession, and healthy exit paths.","risk":"Opaque power and ownership rules invite conflict or guild collapse.","signal":"active member distribution, succession success, and retention by guild"},{"id":"presence","section":"server","title":"Presence and availability","purpose":"Show enough player availability to help others connect while respecting privacy.","risk":"Presence leakage can enable harassment or unwanted tracking.","signal":"invite acceptance, block effectiveness, and visibility preferences"},{"id":"chat-architecture","section":"server","title":"Chat and communication channels","purpose":"Route conversation by context, with useful moderation and accessibility controls.","risk":"One global channel creates noise and abuse at scale.","signal":"message delivery, report resolution, and mute usage"},{"id":"reconnection","section":"server","title":"Reconnect and session recovery","purpose":"Restore a player to a valid, safe state after network or process interruption.","risk":"A crash that loses progress or group context destroys trust.","signal":"rejoin success, state rollback, and recovery duration"},{"id":"persistence","section":"server","title":"World and character persistence","purpose":"Persist durable player and world changes with explicit ownership and recovery semantics.","risk":"Partial saves can duplicate, erase, or contradict progress.","signal":"save acknowledgement, rollback depth, and inconsistency count"},{"id":"schema-migration","section":"server","title":"Schema evolution and migration","purpose":"Change stored data with reversible, observable migrations and tested compatibility windows.","risk":"A one-way migration can turn a routine patch into player data loss.","signal":"migration error rate and rollback time"},{"id":"database-modeling","section":"server","title":"Database and state modeling","purpose":"Separate durable facts, derived views, and short-lived simulation state deliberately.","risk":"A single overloaded store couples live simulation to slow reporting.","signal":"write amplification and query isolation"},{"id":"tick-scheduler","section":"server","title":"Simulation tick scheduling","purpose":"Run bounded fixed simulation steps and manage overload without unstable catch-up.","risk":"Unbounded catch-up spirals after a stall.","signal":"tick variance, backlog depth, and dropped cosmetic work"},{"id":"time-model","section":"server","title":"Clock and time model","purpose":"Define authoritative time for cooldowns, world schedules, and durable deadlines.","risk":"Mixing client clocks and server clocks creates exploits and confusing timers.","signal":"clock drift, expiry disagreement, and timer anomalies"},{"id":"protocol-versioning","section":"server","title":"Protocol and version compatibility","purpose":"Evolve messages safely across clients, services, and deployment versions.","risk":"A mismatched client can corrupt state or fail without explanation.","signal":"version handshake failures and mixed-version coverage"},{"id":"combat-readability","section":"combat","title":"Combat readability","purpose":"Make threat, range, timing, and outcome legible under effects and multiplayer overlap.","risk":"Visual noise makes skill expression indistinguishable from confusion.","signal":"telegraph recognition and avoidable-damage rate"},{"id":"action-combat","section":"combat","title":"Action combat","purpose":"Reward movement, timing, aiming, and positioning while keeping server outcomes consistent.","risk":"Latency-sensitive windows may privilege geography or hardware.","signal":"input-to-outcome latency and region fairness"},{"id":"tab-target-combat","section":"combat","title":"Targeted combat","purpose":"Make target choice and ability sequencing clear under groups, pets, and moving enemies.","risk":"Target churn and hidden rules obscure player agency.","signal":"target acquisition time and invalid-target actions"},{"id":"ability-design","section":"combat","title":"Ability and skill design","purpose":"Give each ability a readable purpose, cost, counterplay, and place in a build.","risk":"A mandatory button tax narrows build choice.","signal":"pick rate, ability overlap, and option diversity"},{"id":"class-archetypes","section":"combat","title":"Class and archetype design","purpose":"Create complementary identities that stay useful across group sizes and content types.","risk":"Hard role locks can block friends from playing together.","signal":"composition diversity and role queue health"},{"id":"buildcraft","section":"combat","title":"Buildcraft and loadouts","purpose":"Support expressive specialization with understandable tradeoffs and affordable experimentation.","risk":"Respec friction makes players afraid to learn.","signal":"build diversity, respec regret, and loadout switching"},{"id":"group-roles","section":"combat","title":"Group role composition","purpose":"Make defensive, supportive, and damage contributions visible and flexible.","risk":"Rigid holy-trinity expectations can bottleneck play.","signal":"group fill time, role substitution, and contribution perception"},{"id":"enemy-ai","section":"combat","title":"Enemy behavior and AI","purpose":"Give enemies consistent rules, believable goals, and counterplay for varied group sizes.","risk":"Unclear AI cheats feel arbitrary; simple AI becomes farmable.","signal":"behavior predictability and exploit frequency"},{"id":"threat-and-aggro","section":"combat","title":"Threat and aggro","purpose":"Communicate target pressure and let groups influence it through intentional play.","risk":"Hidden threat tables force external tools and blame.","signal":"target-switch comprehension and role agency"},{"id":"crowd-control","section":"combat","title":"Control and status effects","purpose":"Use control to create tactical decisions while preserving response and accessibility.","risk":"Long control chains remove participation.","signal":"control downtime, diminishing-return clarity, and counter-use"},{"id":"combat-effects","section":"combat","title":"Damage, healing, and effects","purpose":"Resolve combat consistently, transparently, and with enough guardrails for balance.","risk":"Stacking edge cases and rounding create unexplained outcomes.","signal":"simulation determinism and combat-log agreement"},{"id":"boss-encounters","section":"combat","title":"Boss encounter design","purpose":"Build encounters around readable phases, changing priorities, and fair recovery.","risk":"Single-puzzle fights become solved scripts with little adaptation.","signal":"phase comprehension and recovery after mistakes"},{"id":"dungeon-design","section":"combat","title":"Dungeon design","purpose":"Create compact cooperative spaces with navigation, combat, story, and reward cadence.","risk":"Linear hallways over-reward speed and under-reward attention.","signal":"time by route, optional discovery, and wipe recovery"},{"id":"raid-design","section":"combat","title":"Raid and large-group design","purpose":"Coordinate many players through legible mechanics and scalable participation roles.","risk":"Complexity that depends on perfect voice coordination excludes players.","signal":"completion by group style and mechanic failure clusters"},{"id":"pvp-fairness","section":"combat","title":"PvP fairness and rules","purpose":"Offer competitive stakes with legible rules, counterplay, and protections against griefing.","risk":"Unbounded power gaps turn PvP into target practice.","signal":"match fairness, spawn safety, and repeat participation"},{"id":"pvp-matchmaking","section":"combat","title":"PvP matchmaking","purpose":"Create matches that balance skill, latency, premade status, and queue health.","risk":"A hidden rating system can feel punitive or impossible to understand.","signal":"rating calibration, stomp rate, and queue time"},{"id":"large-scale-war","section":"combat","title":"Large-scale faction warfare","purpose":"Make territory, logistics, and battlefield contribution meaningful at high concurrency.","risk":"Zerg dominance and lag can erase strategic play.","signal":"objective diversity, latency by population, and comeback agency"},{"id":"spectator-and-replay","section":"combat","title":"Spectating and replay","purpose":"Help players learn from events without revealing hidden state or enabling collusion.","risk":"Information leaks can compromise competitive integrity.","signal":"observer parity and replay desync"},{"id":"bot-and-companion","section":"combat","title":"Companion and bot behavior","purpose":"Let AI allies cover gaps and teach mechanics without replacing player choice.","risk":"Overpowered helpers flatten social play; weak helpers frustrate solo players.","signal":"companion dependency and command clarity"},{"id":"combat-accessibility","section":"combat","title":"Combat accessibility","purpose":"Offer adjustable input, timing, visual, and audio support while preserving core decisions.","risk":"Accessibility presets that hide information can make players less safe.","signal":"settings adoption and success parity by setting"},{"id":"quest-framework","section":"progression","title":"Quest structure and state","purpose":"Represent objectives, prerequisites, failure, sharing, and completion as explicit state.","risk":"Ambiguous state blocks progression or creates accidental skips.","signal":"stuck rates and progress reconciliation"},{"id":"branching-story","section":"progression","title":"Branching narrative","purpose":"Make player choices meaningful through remembered consequences and coherent convergence.","risk":"Cosmetic choices presented as irreversible betrayals weaken trust.","signal":"choice recognition and replay value"},{"id":"dialogue","section":"progression","title":"Dialogue and character voice","purpose":"Give dialogue clear purpose, skippability, state awareness, and distinct voices.","risk":"Long mandatory exposition interrupts player intent.","signal":"dialogue exit rate and recall of key facts"},{"id":"faction-reputation","section":"progression","title":"Factions and reputation","purpose":"Use factions to frame belonging, access, conflict, and multiple viable loyalties.","risk":"Reputation gates can trap players outside content with friends.","signal":"reputation path completion and lockout recovery"},{"id":"exploration","section":"progression","title":"Exploration and discovery","purpose":"Reward curiosity with knowledge, navigational confidence, and optional surprises.","risk":"Checklist maps can convert discovery into rote clearing.","signal":"self-directed route rate and unmarked discovery"},{"id":"world-navigation","section":"progression","title":"Maps and wayfinding","purpose":"Help players orient, plan, and recover without removing environmental learning.","risk":"Poor wayfinding wastes time; excessive pins eliminate discovery.","signal":"navigation reversals and destination confidence"},{"id":"dynamic-world-events","section":"progression","title":"Dynamic world events","purpose":"Connect local actions to visible world changes and shared participation.","risk":"Events that ignore player outcomes feel like disposable chores.","signal":"participation by level, state change visibility, and repeat rate"},{"id":"public-events","section":"progression","title":"Public event participation","purpose":"Allow strangers to join shared challenges with clear contribution and reward rules.","risk":"Unclear credit or late arrival makes public play feel unfair.","signal":"join-in-progress success and perceived reward fairness"},{"id":"solo-path","section":"progression","title":"Solo progression path","purpose":"Let solo players access story and growth while leaving social paths valuable.","risk":"Solo access can become a copy of group content with no distinct texture.","signal":"solo completion parity and optional group conversion"},{"id":"npc-companions","section":"progression","title":"NPC companion progression","purpose":"Use companions to provide story texture and configurable support.","risk":"Companion collection can become a mandatory stat chase.","signal":"dialogue use, support settings, and role substitution"},{"id":"repeatable-content","section":"progression","title":"Repeatable content and variety","purpose":"Refresh familiar activities with changed decisions rather than larger chore lists.","risk":"Random modifiers without strategic consequence become noise.","signal":"repeat activity drop-off and modifier impact"},{"id":"seasonal-content","section":"progression","title":"Seasonal world cadence","purpose":"Create time-bounded stories and goals with clear catch-up and permanence rules.","risk":"Fear-of-missing-out pressure alienates players who take breaks.","signal":"return after season and late-entry completion"},{"id":"daily-weekly-goals","section":"progression","title":"Daily and weekly goals","purpose":"Offer small optional goals that guide players toward varied systems.","risk":"Mandatory daily checklists make leisure feel scheduled.","signal":"goal skip tolerance and activity diversity"},{"id":"achievements","section":"progression","title":"Achievements and milestones","purpose":"Celebrate skill, exploration, cooperation, and personal history.","risk":"Unbounded checklist volume devalues recognition.","signal":"meaningful milestone recall and completion diversity"},{"id":"collections","section":"progression","title":"Collections and journals","purpose":"Turn finding, crafting, and learning into a persistent record of discovery.","risk":"Collection gaps can become opaque item hunts.","signal":"discovery logging and collection completion friction"},{"id":"vertical-progression","section":"progression","title":"Vertical power progression","purpose":"Let power grow without invalidating previous content or excluding new cohorts.","risk":"Power inflation erodes old goals and narrows group access.","signal":"power gap over time and legacy content vitality"},{"id":"horizontal-progression","section":"progression","title":"Horizontal progression","purpose":"Add new strategies, cosmetics, knowledge, or roles without mandatory stat inflation.","risk":"Nominal choice can hide one dominant build.","signal":"option usage and power-normalized participation"},{"id":"account-progression","section":"progression","title":"Account-wide progression","purpose":"Share appropriate unlocks across characters while preserving character identity.","risk":"Duplicated chores frustrate; full sharing can erase meaningful alts.","signal":"repeat-grind time and alt creation"},{"id":"catch-up-and-alts","section":"progression","title":"Catch-up and alternate characters","purpose":"Help returning players and alts reach current social play without deleting journey.","risk":"Boosts with unexplained systems create a confusing competence gap.","signal":"time to join friends and failed activity attempts"},{"id":"level-scaling","section":"progression","title":"Level and content scaling","purpose":"Let mixed-level friends cooperate while preserving understandable risk and reward.","risk":"Scaling can make character growth feel fake.","signal":"mixed-level participation and outcome readability"},{"id":"new-player-legacy","section":"progression","title":"New-player and legacy content","purpose":"Keep a coherent entry path through a world with years of accumulated systems.","risk":"Content accumulation can overwhelm new players with obsolete choices.","signal":"first-hour decision load and old-content completion"},{"id":"itemization","section":"economy","title":"Itemization and equipment","purpose":"Make item choices communicate role, rarity, utility, and opportunity cost.","risk":"Numerical upgrades can crowd out interesting alternatives.","signal":"equip change rate and build diversity"},{"id":"loot-design","section":"economy","title":"Loot table design","purpose":"Make reward probability, eligibility, and pity rules understandable and auditable.","risk":"Unclear variance feels rigged and harms trust.","signal":"distribution drift and unlucky-tail duration"},{"id":"reward-cadence","section":"economy","title":"Reward pacing","purpose":"Reward effort at a pace that respects time and preserves anticipation.","risk":"Too-frequent rewards become clutter; too-rare rewards become unreachable.","signal":"reward spacing and goal completion confidence"},{"id":"rarity-language","section":"economy","title":"Rarity and value language","purpose":"Use labels and visual cues that correctly predict utility, effort, or social meaning.","risk":"Color rarity that does not match value misleads players.","signal":"rarity prediction accuracy"},{"id":"crafting","section":"economy","title":"Crafting and production","purpose":"Make crafting a source of expression, interdependence, and useful output.","risk":"Crafting as a mandatory random barrier feels like a second job.","signal":"recipe diversity and crafted item demand"},{"id":"gathering","section":"economy","title":"Gathering and resource worlds","purpose":"Connect gathering to place, risk, timing, and useful economic decisions.","risk":"Scarcity camping rewards schedule flexibility over mastery.","signal":"node contention and alternative supply routes"},{"id":"recipe-design","section":"economy","title":"Recipes and crafting progression","purpose":"Give recipes legible inputs, meaningful specialization, and sustainable discovery.","risk":"Recipe trees can become opaque dependency spreadsheets.","signal":"time to first craft and blocked-craft frequency"},{"id":"currency-system","section":"economy","title":"Currency and token design","purpose":"Make each currency's source, use, cap, and expiration easy to understand.","risk":"Too many currencies fragment value and obscure decisions.","signal":"currency balances with no intended sink"},{"id":"player-economy","section":"economy","title":"Player-driven economy","purpose":"Let players produce, exchange, and specialize under visible, abuse-resistant rules.","risk":"Unbounded arbitrage and monopolies destabilize the world.","signal":"price volatility and seller concentration"},{"id":"auction-market","section":"economy","title":"Market boards and auctions","purpose":"Make listings discoverable, prices comparable, and settlement reliable.","risk":"Opaque fees and bots disadvantage casual sellers.","signal":"search success, sale completion, and concentration"},{"id":"trade-security","section":"economy","title":"Direct trading and exchange safety","purpose":"Show both sides exactly what will transfer and commit exchanges atomically.","risk":"Last-second swaps and item duplication destroy confidence.","signal":"trade rollback and dispute rate"},{"id":"currency-sinks","section":"economy","title":"Currency sinks and upkeep","purpose":"Remove excess currency through appealing optional choices and transparent services.","risk":"Punitive upkeep punishes inactivity and new players.","signal":"inflation, sink uptake, and returning-player affordability"},{"id":"economic-simulation","section":"economy","title":"Economy simulation and controls","purpose":"Model faucets, sinks, stock, and substitution before live economy changes.","risk":"Isolated tuning misses player adaptation and market feedback.","signal":"faucet-to-sink balance and simulation error"},{"id":"player-shops","section":"economy","title":"Player storefronts and services","purpose":"Give creators and crafters visible ways to offer goods and work.","risk":"Unmoderated storefronts invite scams and inaccessible search.","signal":"shop discovery and transaction disputes"},{"id":"cosmetic-value","section":"economy","title":"Cosmetic reward value","purpose":"Offer cosmetic goals with clarity, collection utility, and earned alternatives.","risk":"Exclusivity pressure can turn style into status coercion.","signal":"cosmetic use diversity and purchase regret"},{"id":"housing","section":"world","title":"Player housing and social spaces","purpose":"Let players build identity, host visitors, and display history in persistent places.","risk":"Housing limits that hide rules create scarcity resentment.","signal":"visit rate, build edits, and guest interactions"},{"id":"building","section":"world","title":"Construction and base building","purpose":"Support creative construction with stable placement, shared permissions, and understandable cost.","risk":"Destructive raids and griefing can erase weeks of effort.","signal":"build survival, permission errors, and collaborative edits"},{"id":"ecology","section":"world","title":"Ecology and creature populations","purpose":"Make creatures and resources respond to place and players in believable, bounded ways.","risk":"Unbounded simulation creates server load and farm loops.","signal":"spawn stability and ecosystem recovery"},{"id":"spawn-systems","section":"world","title":"Spawn selection and respawn","purpose":"Place encounters in a way that preserves discovery and prevents spawn camping.","risk":"Predictable spawn exploitation ruins safety and fairness.","signal":"spawn camping and density variance"},{"id":"world-simulation","section":"world","title":"Persistent world simulation","purpose":"Choose which world facts continue between sessions and how they recover from downtime.","risk":"Always-on simulation can burn capacity without improving player value.","signal":"offline state drift and meaningful world change"},{"id":"weather-time","section":"world","title":"Weather and day-night cycles","purpose":"Use time and weather to change mood and strategy with fair readability.","risk":"Real-world schedules disadvantage players in some regions.","signal":"cycle participation and visibility accessibility"},{"id":"procedural-content","section":"world","title":"Procedural content generation","purpose":"Use rules and authored constraints to produce coherent variations that remain testable.","risk":"Unbounded randomness generates incoherent rooms and impossible states.","signal":"seeded reproducibility and defect density by variation"},{"id":"environmental-storytelling","section":"world","title":"Environmental storytelling","purpose":"Let spaces reveal history and stakes through composition, objects, and interaction.","risk":"Lore only legible to experts becomes decoration.","signal":"observation recall and optional discovery"},{"id":"world-lore-bible","section":"world","title":"World bible and consistency","purpose":"Keep cultures, geography, history, and rules consistent while enabling new authors.","risk":"Canon ambiguity slows teams and alienates attentive players.","signal":"contradiction count and author lookup time"},{"id":"travel-hubs","section":"world","title":"Hubs and social gathering places","purpose":"Place useful services and repeat routes where players can see and meet one another.","risk":"Overcentralization makes regions feel empty.","signal":"encountered strangers and hub dwell behavior"},{"id":"discovery-pacing","section":"world","title":"Discovery pacing","purpose":"Alternate safety, uncertainty, landmarks, and reward so exploration has shape.","risk":"Constant spectacle numbs attention; long quiet stretches lose intent.","signal":"route variation and attention drop-off"},{"id":"zone-pacing","section":"world","title":"Zone sequencing and pacing","purpose":"Guide difficulty, story, travel, and gathering through readable regional arcs.","risk":"Level-number corridors can make the world feel artificial.","signal":"regional completion flow and backtracking burden"},{"id":"environmental-hazards","section":"world","title":"Environmental hazards","purpose":"Make terrain and environmental danger telegraphed, learnable, and relevant to choices.","risk":"Hidden hazards feel arbitrary and can block accessibility.","signal":"hazard recognition and recovery rate"},{"id":"vehicles-and-mounts","section":"world","title":"Vehicles and mounts","purpose":"Use movement tools to add utility and expression without trivializing terrain or combat.","risk":"Speed creep invalidates map scale and traversal builds.","signal":"travel-time compression and mount utility"},{"id":"open-world-bosses","section":"world","title":"Open-world boss events","purpose":"Support spontaneous large encounters with readable roles and resilient participation credit.","risk":"Damage-only credit and server congestion exclude late joiners.","signal":"participation credit and event completion at scale"},{"id":"instance-boundaries","section":"world","title":"Instance boundaries and transitions","purpose":"Make loading, grouping, state handoff, and return points understandable.","risk":"Instance seams separate friends or lose temporary progress.","signal":"failed transitions and party split rate"},{"id":"social-discovery","section":"social","title":"Social discovery","purpose":"Help players find compatible people through activity intent, schedule, and consent.","risk":"Forced social prompts feel intrusive and unsafe.","signal":"opt-in connection and block/report outcomes"},{"id":"mentorship","section":"social","title":"Mentorship and newcomer support","purpose":"Reward experienced players for useful guidance without turning new people into commodities.","risk":"Automated mentor quotas invite spam and exploitation.","signal":"mentor follow-through and newcomer confidence"},{"id":"group-finder","section":"social","title":"Group finder and LFG","purpose":"Communicate activity fit, commitment, language, and accessibility before players join.","risk":"Opaque listings produce mismatched expectations and kick abuse.","signal":"group completion and removal disputes"},{"id":"friendship-and-presence","section":"social","title":"Friends and social graphs","purpose":"Make invitations, cross-server joins, privacy, and offline messages predictable.","risk":"A hidden social graph can create unwanted exposure.","signal":"invite controls and successful reunions"},{"id":"guild-progression","section":"social","title":"Guild goals and shared progress","purpose":"Give groups durable projects, ceremonies, and visible contribution histories.","risk":"Guild power tied to attendance punishes members with changing schedules.","signal":"contribution spread and inactive-member return"},{"id":"group-credit","section":"social","title":"Shared objective credit","purpose":"Award contribution fairly across roles, late joins, healing, support, and discovery.","risk":"Damage-only credit discourages varied play.","signal":"credit disputes by contribution type"},{"id":"cooperative-survival","section":"social","title":"Cooperative survival","purpose":"Turn scarcity, building, danger, and recovery into negotiation rather than blame.","risk":"Shared-world progress can be overwritten or owned unfairly.","signal":"shared-save integrity and conflict resolution"},{"id":"roleplay-tools","section":"social","title":"Roleplay and player storytelling","purpose":"Support identity, emotes, privacy, discovery, and player-run scenes without forcing canon.","risk":"Tools can enable harassment or confusion with official narrative.","signal":"event participation and moderation response"},{"id":"community-events","section":"social","title":"Community-run events","purpose":"Let groups organize clear, safe, repeatable events with lightweight tools.","risk":"Scheduling and prize disputes erode volunteer effort.","signal":"event completion and organizer retention"},{"id":"player-reputation","section":"social","title":"Player reputation and trust signals","purpose":"Use behavior history carefully to help cooperation without creating permanent stigma.","risk":"Opaque scores become social credit punishment.","signal":"false-positive appeals and group access parity"},{"id":"moderation-workflow","section":"social","title":"Moderation workflow","purpose":"Support reporting, safety action, review, appeals, and repeat-abuse handling.","risk":"Slow or unclear moderation makes tools feel cosmetic.","signal":"report acknowledgement and resolution time"},{"id":"anti-harassment","section":"social","title":"Harassment and grief protection","purpose":"Give players control, safe defaults, and context-aware response to unwanted behavior.","risk":"A single block button cannot stop coordinated abuse.","signal":"repeat contact after block and safety feature discoverability"},{"id":"chat-moderation","section":"social","title":"Chat safety and moderation","purpose":"Separate high-volume public communication from trusted/private channels and enforceable controls.","risk":"Automated filters can punish dialects or miss coded harassment.","signal":"appeal reversals and report handling by locale"},{"id":"guild-governance","section":"social","title":"Guild governance and succession","purpose":"Define roles, ownership, voting, records, and recovery when leaders leave.","risk":"Unclear ownership enables theft or grief during conflict.","signal":"leadership recovery and permission audit"},{"id":"async-social","section":"social","title":"Asynchronous social connection","purpose":"Let players share goals and useful traces when schedules do not overlap.","risk":"Passive systems can expose locations or become notification spam.","signal":"asynchronous help accepted and notification dismissals"},{"id":"UGC-tools","section":"social","title":"Creator and user-generated content tools","purpose":"Give creators clear constraints, reusable components, preview, attribution, and safe publication.","risk":"A powerful editor without guardrails amplifies risk and support cost.","signal":"publish success and moderation rework"},{"id":"UGC-safety","section":"social","title":"User-generated content safety","purpose":"Review, report, label, and remove community content with proportionate, auditable controls.","risk":"Poor enforcement creates harm; overreach silences harmless creativity.","signal":"review precision and appeal outcomes"},{"id":"community-marketplace","section":"social","title":"Creator marketplace and attribution","purpose":"Reward useful creative work with transparent discovery, rights, and payout rules.","risk":"Opaque exposure and rights terms damage creator trust.","signal":"creator retention and appeal resolution"},{"id":"crossplay-communities","section":"social","title":"Cross-platform community design","purpose":"Preserve social identity, input fairness, and moderation across platform boundaries.","risk":"Platform silos split friends and support policy conflicts.","signal":"cross-platform reunion success and input fairness"},{"id":"content-pipeline","section":"production","title":"Content production pipeline","purpose":"Turn design intent into versioned, reviewable, testable assets and live data.","risk":"Manual handoffs create late defects and stale references.","signal":"rework rate and time from draft to verified release"},{"id":"authoring-tools","section":"production","title":"Designer authoring tools","purpose":"Give designers safe, inspectable controls over content without requiring code for every edit.","risk":"Hidden dependencies make tools fast until they are dangerous.","signal":"authoring time and invalid-state prevention"},{"id":"content-validation","section":"production","title":"Content validation and linting","purpose":"Catch broken references, impossible rewards, missing text, and invalid gates before play.","risk":"A green build that ignores player state is false confidence.","signal":"defects caught before test and validator escape rate"},{"id":"procedural-testing","section":"production","title":"Procedural content testing","purpose":"Exercise generated variation with fixed seeds, coverage budgets, and known-good examples.","risk":"Random QA cannot reproduce a rare broken layout.","signal":"seed replay success and invalid layouts found"},{"id":"quest-authoring","section":"production","title":"Quest authoring workflow","purpose":"Let writers and designers express state, branching, localization, and recovery explicitly.","risk":"Story content with hidden state assumptions becomes brittle.","signal":"quest validation coverage and stuck-player reports"},{"id":"narrative-delivery","section":"production","title":"Narrative delivery","purpose":"Balance voice, pacing, skip controls, recap, and multiplayer synchronization.","risk":"Group members at different story states can invalidate scenes.","signal":"dialogue sync and story abandonment"},{"id":"localization","section":"production","title":"Localization and writing pipeline","purpose":"Design text and UI for expansion, tone, context, and linguistic review from the start.","risk":"Late string extraction breaks layout and narrative meaning.","signal":"string overflow and linguistic defect rate"},{"id":"accessibility","section":"production","title":"Accessibility strategy","purpose":"Make essential information, controls, and social participation usable through varied needs.","risk":"Accessibility added as a final checklist cannot fix system-level barriers.","signal":"task success across input, vision, hearing, and cognition settings"},{"id":"ui-information-architecture","section":"production","title":"Interface information architecture","purpose":"Show the next useful choice without burying the world under alerts and panes.","risk":"Too many panels fragment attention and increase cognitive load.","signal":"task completion and menu return loops"},{"id":"inventory-management","section":"production","title":"Inventory and storage","purpose":"Make ownership, filters, stacks, weight, sorting, and recovery understandable.","risk":"Inventory limits convert play into frequent administrative interruptions.","signal":"time in inventory and accidental loss rate"},{"id":"telemetry-design","section":"production","title":"Telemetry and event design","purpose":"Collect only the signals needed to answer a design or reliability question.","risk":"Unbounded logging raises cost and captures sensitive data without purpose.","signal":"decision coverage and privacy review completion"},{"id":"experimentation","section":"production","title":"Experiments and rollout tests","purpose":"Test changes with guardrails, representative cohorts, and rollback-ready interpretation.","risk":"Poor experiment design confounds player mix and creates false wins.","signal":"metric confidence and guardrail breaches"},{"id":"balance-process","section":"production","title":"Balance tuning process","purpose":"Change one coherent set of levers at a time and preserve testable rationale.","risk":"Reactive tuning whiplashes players and makes regressions hard to trace.","signal":"change attribution and regression frequency"},{"id":"liveops-calendar","section":"production","title":"Live operations calendar","purpose":"Coordinate events, patches, support coverage, and rest windows across regions.","risk":"Permanent urgency burns both players and teams.","signal":"calendar collision rate and participation health"},{"id":"patch-notes","section":"production","title":"Patch communication and release notes","purpose":"Explain player-visible behavior changes, known issues, and remedies in plain language.","risk":"Vague notes make a correct fix look like secrecy.","signal":"support-ticket deflection and player comprehension"},{"id":"player-feedback","section":"production","title":"Player feedback loop","purpose":"Acknowledge, classify, investigate, and close the loop on representative feedback.","risk":"Listening without visible follow-up trains players to stop reporting.","signal":"feedback disposition time and close-loop visibility"},{"id":"community-communication","section":"production","title":"Community communication","purpose":"Set expectations on plans, uncertainty, service changes, and moderation with consistency.","risk":"Overpromising makes normal iteration feel like betrayal.","signal":"promise accuracy and repeated clarification requests"},{"id":"content-retirement","section":"production","title":"Content sunset and preservation","purpose":"Retire or rotate content with advance notice, compensation rules, and preserved history.","risk":"Permanent removal destroys player investment and cultural memory.","signal":"sunset surprise and preserved-progress satisfaction"},{"id":"monetization-ethics","section":"production","title":"Monetization and trust","purpose":"Price convenience and expression transparently while protecting power, consent, and play value.","risk":"Dark patterns and pressure mechanics damage the social contract.","signal":"purchase regret, complaint rate, and nonpayer participation parity"},{"id":"platform-and-policy","section":"production","title":"Platform and policy constraints","purpose":"Translate platform rules into product behavior without fragmenting player safety or ownership.","risk":"Late compliance changes can break accounts and release plans.","signal":"policy defects before launch and account-resolution time"},{"id":"identity-auth","section":"operations","title":"Identity, accounts, and authentication","purpose":"Protect account recovery and session ownership without exposing unnecessary personal data.","risk":"Weak recovery invites theft; excessive friction locks out real owners.","signal":"account takeover and successful recovery rate"},{"id":"authorization","section":"operations","title":"Permissions and capability boundaries","purpose":"Grant each player, service, and tool only the actions it needs, then audit changes.","risk":"Broad permissions turn one compromised account into world-wide damage.","signal":"denied unauthorized action and audit coverage"},{"id":"privacy","section":"operations","title":"Player privacy and data handling","purpose":"Collect, expose, retain, and delete data according to clear purpose and player control.","risk":"Telemetry and social features can reveal sensitive patterns.","signal":"retention compliance and privacy setting effectiveness"},{"id":"anti-exploit","section":"operations","title":"Exploit prevention and response","purpose":"Assume every client can be modified and protect high-value state with layered validation.","risk":"Single-point detection creates easy bypasses and false confidence.","signal":"economic anomaly resolution and false-positive appeals"},{"id":"economy-integrity","section":"operations","title":"Economy integrity controls","purpose":"Detect duplication, bot supply, collusion, and abnormal flows without punishing ordinary variance.","risk":"Automated bans based on one signal punish legitimate players.","signal":"case accuracy and recovery time"},{"id":"backup-recovery","section":"operations","title":"Backup and disaster recovery","purpose":"Restore service and player state to tested recovery objectives with accountable runbooks.","risk":"Untested backups are assumptions, not protection.","signal":"restore drill duration and verified recovery point"},{"id":"deployment","section":"operations","title":"Deployment and release safety","purpose":"Ship small observable changes with compatibility, health checks, and staged exposure.","risk":"Big-bang releases widen outages and make causality unclear.","signal":"rollback time and blast radius"},{"id":"rollback","section":"operations","title":"Rollback and feature containment","purpose":"Disable or revert a faulty feature without corrupting persistent player state.","risk":"A code rollback alone may leave bad data or broken content.","signal":"time to contain and state repair success"},{"id":"incident-response","section":"operations","title":"Incident response","purpose":"Give responders shared severity, ownership, communication, and decision rules.","risk":"Unclear command wastes time and amplifies player impact.","signal":"time to acknowledge, mitigate, and communicate"},{"id":"reliability-slo","section":"operations","title":"Reliability objectives and SLOs","purpose":"Set service targets around player outcomes, error budgets, and regional experience.","risk":"One global uptime score hides broken game actions.","signal":"successful player actions and error-budget consumption"},{"id":"observability","section":"operations","title":"Logs, metrics, and traces","purpose":"Connect player-visible failures to service boundaries while controlling cost and sensitive data.","risk":"Uncorrelated logs slow diagnosis and encourage unsafe data capture.","signal":"time to isolate and trace coverage"},{"id":"capacity","section":"operations","title":"Capacity and load engineering","purpose":"Find the true concurrency, burst, storage, and event bottlenecks with realistic traffic.","risk":"Average load hides launch and event peaks.","signal":"headroom by dependency and saturation duration"},{"id":"regional-latency","section":"operations","title":"Regional latency and infrastructure","purpose":"Place authoritative services and traffic paths around player geography and fairness needs.","risk":"Poor placement adds avoidable latency or excludes underserved regions.","signal":"p95 latency by route and completion parity"},{"id":"security-reviews","section":"operations","title":"Security review and threat modeling","purpose":"Review trust boundaries, content upload, economy, account, and operations paths continuously.","risk":"Security checks done only before launch miss evolving abuse.","signal":"threat coverage and fix lead time"},{"id":"moderation-operations","section":"operations","title":"Trust and safety operations","purpose":"Staff tools, queues, escalation, evidence access, and appeal paths to fit real incident volume.","risk":"A policy without operating capacity is not player protection.","signal":"case backlog and appeal turnaround"},{"id":"service-status","section":"operations","title":"Status communication and maintenance","purpose":"Tell players what is affected, who is affected, and when useful updates will arrive.","risk":"Silence during outages becomes its own reliability failure.","signal":"update cadence and status accuracy"},{"id":"cross-platform","section":"operations","title":"Cross-platform compatibility","purpose":"Share accounts and activities while respecting platform capabilities, privacy, and control differences.","risk":"Platform parity gaps fragment social play.","signal":"cross-play session success and platform feature parity"},{"id":"migration-versioning","section":"operations","title":"Client and server version rollout","purpose":"Support controlled compatibility windows, required updates, and clear migration failures.","risk":"Mixed versions expose protocol and content mismatches.","signal":"version skew duration and failed handshake rate"},{"id":"test-strategy","section":"operations","title":"Test strategy and quality gates","purpose":"Combine deterministic tests, simulation, contract validation, and representative human playtests.","risk":"Unit checks cannot detect social or pacing failures.","signal":"defect escape by category and release-blocking coverage"},{"id":"release-readiness","section":"operations","title":"Release readiness and gates","purpose":"Require known owners, support plans, rollback paths, and player-facing communication before launch.","risk":"Ship pressure can hide unresolved systemic risks.","signal":"readiness exceptions and post-launch severity"},{"id":"economic-abuse","section":"operations","title":"Fraud and abuse economics","purpose":"Model bots and exploiters as adaptive actors and minimize profitable abuse windows.","risk":"Punishment after value has moved cannot restore confidence.","signal":"time-to-detect and recoverable illicit value"},{"id":"data-governance","section":"operations","title":"Data governance and retention","purpose":"Define ownership, deletion, access, and purpose for each player data class.","risk":"Unclear retention compounds privacy and migration risk.","signal":"data inventory completeness and deletion verification"},{"id":"platform-safety","section":"operations","title":"Cross-platform safety controls","purpose":"Coordinate reporting, block lists, parental settings, and identity across services.","risk":"Different safety behavior across platforms creates loopholes.","signal":"cross-platform block effectiveness"},{"id":"end-of-life","section":"operations","title":"Service end-of-life planning","purpose":"Preserve access, purchases, community records, and clear notice when live service ends.","risk":"Abrupt closure strands player time and money.","signal":"notice lead time and preservation completion"}];
function listPlaybooks(){return Object.keys(modules);}
function loadPlaybook(id){const load=modules[id];if(!load)throw new Error('Unknown playbook: '+id);return load();}
function searchPlaybooks(query){const q=String(query||'').toLowerCase();return summaries.filter(p=>(p.title+' '+p.purpose+' '+p.risk+' '+p.signal).toLowerCase().includes(q));}
module.exports={listPlaybooks,loadPlaybook,searchPlaybooks};
